-- #4337 (part of #434 Slice C) — stamp_signing_keys.id as the migration's identity.
-- Migration 20261109213000_signature_ceremony_stamp (and signing-invariants.sql, its verbatim copy) creates the column
-- as `integer GENERATED BY DEFAULT AS IDENTITY`. On the dev and test path `db push` creates the table first, from
-- schema.prisma's @default(autoincrement()), as DEFAULT nextval('stamp_signing_keys_id_seq') with an owned sequence, so
-- that CREATE TABLE IF NOT EXISTS is skipped. This is a separate file because signing-invariants.sql must stay
-- byte-identical to the migration's tail (src/lib/signing/schema1632.test.ts).
--
-- An identity BY DEFAULT is left alone (a re-run changes nothing). Push's exact sequence default, backed by the
-- sequence this column owns, is replaced by the identity, which then continues above the highest existing id. Anything
-- else (an ALWAYS identity, another default, a same-name sequence the column does not own) refuses with what was found.
-- Prisma reads the identity as autoincrement(), so a later db push leaves it (probed). The migration is the authority
-- (ops:alpha:prisma-deploy-flow). One DO block: atomic.
-- Pinned by src/test/migrations/stampKeyIdentity4337.test.ts and the migration replay check.
DO $$
DECLARE
  rel regclass := to_regclass(quote_ident(current_schema()) || '.stamp_signing_keys');
  ident text;
  col_default text;
  default_seq oid;
  owned_seq oid;
  top integer;
BEGIN
  SELECT a.attidentity::text, pg_get_expr(d.adbin, d.adrelid) INTO ident, col_default
    FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
    WHERE a.attrelid = rel AND a.attname = 'id';
  IF ident = 'd' THEN
    RETURN;
  ELSIF ident = 'a' THEN
    RAISE EXCEPTION 'stamp_signing_keys.id is GENERATED ALWAYS, not BY DEFAULT AS IDENTITY; refusing to change it (hadron-server#4337)';
  ELSIF col_default IS DISTINCT FROM 'nextval(''stamp_signing_keys_id_seq''::regclass)' THEN
    RAISE EXCEPTION 'stamp_signing_keys.id has default %, not push''s sequence; refusing to change it (hadron-server#4337)', coalesce(col_default, '(none)');
  ELSIF pg_get_serial_sequence(quote_ident(current_schema()) || '.stamp_signing_keys', 'id') IS DISTINCT FROM
        quote_ident(current_schema()) || '.stamp_signing_keys_id_seq' THEN
    -- The default names the right sequence, but only a sequence OWNED BY this column is push's to drop (#4691 BLIND F1).
    RAISE EXCEPTION 'stamp_signing_keys_id_seq is not owned by stamp_signing_keys.id; refusing to drop it (hadron-server#4337)';
  END IF;
  -- By OID, not by name (#4691 BLIND delta F1): the sequence the default depends on must be the one the column owns.
  -- With that and the text check above, the unqualified DROP below can only reach the owned sequence: a same-name
  -- sequence that shadows the schema's (a temporary one) either holds the default (this check refuses) or makes the
  -- owned one render schema-qualified (the text check refuses); with no shadow, the name resolves in current_schema(),
  -- where the owned sequence is. (The DROP stays a literal: post-push's inventory refuses DDL built at run time.)
  -- The default also depends on its own column (the table's row in pg_depend), so only a SEQUENCE it depends on counts.
  SELECT dep.refobjid INTO default_seq
    FROM pg_attrdef ad JOIN pg_depend dep ON dep.classid = 'pg_attrdef'::regclass AND dep.objid = ad.oid
                                         AND dep.refclassid = 'pg_class'::regclass
                       JOIN pg_class seq ON seq.oid = dep.refobjid AND seq.relkind = 'S'
    WHERE ad.adrelid = rel AND ad.adnum = (SELECT attnum FROM pg_attribute WHERE attrelid = rel AND attname = 'id');
  owned_seq := pg_get_serial_sequence(quote_ident(current_schema()) || '.stamp_signing_keys', 'id')::regclass;
  IF default_seq IS DISTINCT FROM owned_seq THEN
    RAISE EXCEPTION 'stamp_signing_keys.id''s default uses a sequence other than the one the column owns; refusing to drop it (hadron-server#4337)';
  END IF;
  EXECUTE $ddl$ALTER TABLE stamp_signing_keys ALTER COLUMN id DROP DEFAULT$ddl$;
  -- A literal name, by design (Ada's ruling on #4691): post-push's inventory refuses DDL built at run time (EXECUTE
  -- format), so a catalog-derived, schema-qualified DROP is not possible here. The checks above bound this literal to
  -- the owned sequence: the default depends on it by OID, the column owns it, and the default's text names it unqualified.
  EXECUTE $ddl$DROP SEQUENCE stamp_signing_keys_id_seq$ddl$;
  EXECUTE $ddl$ALTER TABLE stamp_signing_keys ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY$ddl$;
  -- Continue above the highest id. With none at 1 or above (an empty table, or only explicit ids of 0 or less), the
  -- identity's own start, 1, is already above every row, and setval below its minimum would fail (#4691 LOCAL F1).
  SELECT max(id) INTO top FROM stamp_signing_keys;
  IF top >= 1 THEN
    PERFORM setval(pg_get_serial_sequence(quote_ident(current_schema()) || '.stamp_signing_keys', 'id'), top);
  END IF;
END $$;
